13 | /// 测试替身：第 `trip_after` 次 `is_cancelled` 起变为 true。
14 | #[derive(Clone)]
15 | pub struct Cancel {
16 |     flag: Arc<AtomicBool>,
17 |     checks: Arc<AtomicUsize>,
18 |     trip_after: usize,
19 | }
20 | 
21 | impl Cancel {
22 |     pub fn trip_after(checks: usize) -> Self {
23 |         Self {
24 |             flag: Arc::new(AtomicBool::new(false)),
25 |             checks: Arc::new(AtomicUsize::new(0)),
26 |             trip_after: checks,
27 |         }
28 |     }
29 | 
30 |     pub fn is_cancelled(&self) -> bool {
31 |         let n = self.checks.fetch_add(1, Ordering::SeqCst) + 1;
32 |         if n >= self.trip_after {
33 |             self.flag.store(true, Ordering::SeqCst);
34 |         }
35 |         self.flag.load(Ordering::SeqCst)
36 |     }
37 | }
