/// Scans cooperatively, preserving hits found before cancellation.
pub fn scan(files: &[(String, String)], needle: &str, cancel: &Cancel) -> (Vec<Hit>, bool) {
    let mut hits = Vec::new();
    for (path, body) in files {
        if cancel.is_cancelled() {
            return (hits, true);
        }

        for (index, line) in body.lines().enumerate() {
            if line.contains(needle) {
                hits.push(Hit {
                    file: path.clone(),
                    line: index + 1,
                    text: line.to_string(),
                });
            }

            if (index + 1) % 8 == 0 && cancel.is_cancelled() {
                return (hits, true);
            }
        }
    }
    (hits, false)
}

